def _safe_requests_get(url, *, timeout, headers=None, cookies=None,
                       max_redirects=5, max_bytes=None):
    # Compatibility arguments cannot expand canonical limits or attach headers.
    if cookies:
        raise ValueError("MENU_COOKIES_FORBIDDEN")
    return _remote_fetch(url, max_bytes=max_bytes, max_redirects=max_redirects)


def loggable_url(url):
    """scheme://host only, with path redacted; no userinfo, query or fragment.

    A menu URL is caller-supplied and its query string can carry a token or a
    signed-URL signature; server logs get the location, never the credential
    (triage 2026-09-30 #7). Never raises: an unparsable value logs as a constant.
    """
    from urllib.parse import urlsplit
    try:
        parts = urlsplit(str(url))
        host = parts.hostname or ""
        if not (parts.scheme and host):
            return "<unparsable-url>"
        return f"{parts.scheme}://{host}/<path-redacted>"
    except Exception:
        return "<unparsable-url>"


def _validate_menu_url(url):
    from urllib.parse import urlparse, urlunparse, parse_qs, urlencode

    url = url.strip()
    if not url:
        return None, None, "URL gerekli."

    try:
        _strict_url(url)
        parsed = urlparse(url)
    except ValueError as e:
        return None, None, str(e)

    tracking_params = {"utm_source", "utm_medium", "utm_campaign", "utm_term",
                       "utm_content", "fbclid", "gclid", "ref", "source"}
    qs = parse_qs(parsed.query, keep_blank_values=False)
    cleaned_qs = {k: v for k, v in qs.items() if k.lower() not in tracking_params}
    clean_query = urlencode(cleaned_qs, doseq=True) if cleaned_qs else ""
    clean_url = urlunparse((parsed.scheme, parsed.netloc, parsed.path,
                            parsed.params, clean_query, ""))
    return urlparse(clean_url), clean_url, None


def _fetch_page(url, timeout=10):
    resp = _remote_fetch(url)
    resp.raise_for_status()
    if resp.headers["Content-Type"] not in {"text/html", "application/xhtml+xml", "text/plain", "text/csv"}:
        raise ValueError("MENU_MEDIA_UNSUPPORTED")
    return resp


def _is_google_drive_url(url):
    from urllib.parse import urlsplit
    try:
        return urlsplit(url).hostname in {"drive.google.com", "docs.google.com"}
    except ValueError:
        return False


def _extract_drive_file_id(url):
    import re
    patterns = [
        r'/file/d/([a-zA-Z0-9_-]+)',
        r'/document/d/([a-zA-Z0-9_-]+)',
        r'/spreadsheets/d/([a-zA-Z0-9_-]+)',
        r'/presentation/d/([a-zA-Z0-9_-]+)',
        r'[?&]id=([a-zA-Z0-9_-]+)',
        r'/open\?id=([a-zA-Z0-9_-]+)',
    ]
    for pat in patterns:
        m = re.search(pat, url)
        if m:
            return m.group(1)
    return None


def _get_drive_direct_url(url, file_id):
    if "docs.google.com/document" in url:
        return f"https://docs.google.com/document/d/{file_id}/export?format=txt", "doc"
    if "docs.google.com/spreadsheets" in url:
        return f"https://docs.google.com/spreadsheets/d/{file_id}/export?format=csv", "sheet"
    return f"https://drive.google.com/uc?export=download&id={file_id}", "file"


def _process_google_drive_url(url):
    import requests as http_req

    file_id = _extract_drive_file_id(url)
    if not file_id:
        return None, "Google Drive bağlantısından dosya kimliği çıkarılamadı."

    direct_url, url_type = _get_drive_direct_url(url, file_id)
    _DRIVE_MAX_BYTES = _MAX_FETCH_BYTES

    try:
        # SSRF-safe: validates + pins every redirect hop (Google's export
        # endpoints redirect to googleusercontent.com, which resolves public).
        resp = _safe_requests_get(direct_url, timeout=30, headers={
            "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/125.0.0.0 Safari/537.36",
        })
    except ValueError as e:
        if str(e) in {"MENU_MEDIA_UNSUPPORTED", "MENU_ENCODING_UNSUPPORTED", "MENU_BODY_LIMIT", "MENU_PARSE_LIMIT"}:
            return None, str(e)
        return None, "Google Drive bağlantısı çözümlenemedi."
    except http_req.exceptions.Timeout:
        return None, "Google Drive dosyası indirilemedi — zaman aşımı."
    except http_req.exceptions.RequestException as e:
        return None, f"Google Drive bağlantı hatası: {type(e).__name__}"

    if resp.status_code in (403, 401):
        return None, json.dumps({
            "success": False,
            "error": "GOOGLE_DRIVE_LINK_RESTRICTED",
            "message": "Bu menü dosyası gizli olarak ayarlanmış. Lütfen Drive üzerinden dosya iznini 'Bağlantıya sahip olan herkes görüntüleyebilir' olarak değiştirip tekrar deneyin."
        })
    if resp.status_code == 404:
        return None, "Google Drive dosyası bulunamadı. Lütfen bağlantıyı kontrol edin."
    if resp.status_code != 200:
        return None, f"Google Drive hatası: HTTP {resp.status_code}"

    # B19: Content-Length sayısal olmayabilir (bozuk/uyumsuz sunucu); int()
    # ham ValueError'ı çağıranın koruması dışında patlatırdı. Güvenle ayrıştır;
    # ayrıştırılamıyorsa boyut kapısını atla (aşağıdaki streaming cap yine korur).
    content_length = resp.headers.get("Content-Length")
    declared_bytes = None
    if content_length:
        try:
            declared_bytes = int(content_length)
        except (TypeError, ValueError):
            declared_bytes = None
    if declared_bytes is not None and declared_bytes > _DRIVE_MAX_BYTES:
        resp.close()
        size_mb = declared_bytes // (1024 * 1024)
        return None, f"Dosya çok büyük ({size_mb}MB). Maksimum 3MB desteklenir. Lütfen dosyayı küçültüp tekrar deneyin."

    content_type = resp.headers.get("Content-Type", "").lower()
    chunks = []
    downloaded = 0
    for chunk in resp.iter_content(chunk_size=256 * 1024):
        downloaded += len(chunk)
        if downloaded > _DRIVE_MAX_BYTES:
            resp.close()
            return None, "Dosya çok büyük (maks 3MB). Lütfen dosyayı küçültüp tekrar deneyin."
        chunks.append(chunk)
    file_bytes = b"".join(chunks)

    current_app.logger.info(f"[DRIVE] Downloaded {len(file_bytes)} bytes")

    preview_lower = file_bytes[:5000].lower()
    is_drive_confirm = ("text/html" in content_type and
                        (b"virus scan" in preview_lower or b"download anyway" in preview_lower
                         or b"uc-download-link" in preview_lower or b"confirm=" in preview_lower))
    if is_drive_confirm:
        return None, "MENU_DRIVE_CONFIRMATION_UNSUPPORTED"

    if "application/pdf" in content_type or file_bytes.lstrip().startswith(b"%PDF-"):
        return None, "MENU_MEDIA_UNSUPPORTED"
    if content_type.split(";", 1)[0].strip() not in {"text/plain", "text/csv", "text/html", "application/xhtml+xml"}:
        return None, "MENU_MEDIA_UNSUPPORTED"

    if "text/plain" in content_type or "text/csv" in content_type:
        current_app.logger.info(f"[DRIVE] Dispatching as plain text")
        try:
            text = file_bytes.decode("utf-8", errors="replace")
        except Exception:
            text = file_bytes.decode("latin-1", errors="replace")
        if text and len(text.strip()) > 20:
            text = _sanitize_menu_text(text[:40000])[:40000]
            current_app.logger.info(f"[DRIVE] Text extracted: {len(text)} chars")
            title = "Google Drive Doküman Menü" if url_type == "doc" else "Google Drive Menü"
            return {"title": title, "body_text": text, "headings": [], "source_url": url, "menu_source": "google_drive"}, None
        return None, "Dosyadan menü metni çıkarılamadı."

    if content_type.split(";", 1)[0] in {"text/html", "application/xhtml+xml"}:
        try:
            soup = bounded_soup(file_bytes.decode("utf-8", errors="replace"))
        except ValueError:
            return None, "MENU_PARSE_LIMIT"
        for tag in soup(["script", "style", "link", "meta"]):
            tag.decompose()
        text = bounded_text(soup)
        if text and len(text.strip()) > 20:
            text = _sanitize_menu_text(text[:40000])[:40000]
            current_app.logger.info(f"[DRIVE] HTML fallback extracted: {len(text)} chars")
            return {"title": "Google Drive Menü", "body_text": text, "headings": [], "source_url": url, "menu_source": "google_drive"}, None

    return None, f"Desteklenmeyen dosya tipi: {content_type.split(';')[0]}"
